-- Reconcile staging-only schema drift against the current production catalog (2026-10-25).
-- Restores missing application tables, their indexes/RLS/policies/triggers and the current server RPC definitions.
-- This migration performs no data backfill. Existing production tables are left in place by CREATE TABLE IF NOT EXISTS.
SET search_path TO public, pg_temp;

-- Reconcile shared dependencies used by current offline/admin RPCs without rewriting rows.
ALTER TABLE public.offline_sync_operations
  ADD COLUMN IF NOT EXISTS request_fingerprint text;

ALTER TABLE public.notification_messages
  ALTER COLUMN scheduled_at SET DEFAULT now();

DO $scheduled_at_reconcile$
BEGIN
  IF EXISTS (SELECT 1 FROM public.notification_messages WHERE scheduled_at IS NULL) THEN
    RAISE EXCEPTION 'NOTIFICATION_SCHEDULED_AT_NULLS_REQUIRE_REVIEW';
  END IF;
END
$scheduled_at_reconcile$;

ALTER TABLE public.notification_messages
  ALTER COLUMN scheduled_at SET NOT NULL;

CREATE TABLE IF NOT EXISTS public.access_recovery_requests (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  tenant_id bigint NOT NULL,
  owner_user_id bigint,
  requested_by_user_id bigint NOT NULL,
  method text DEFAULT 'oauth_invite'::text NOT NULL,
  status text DEFAULT 'pending'::text NOT NULL,
  note text,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  completed_at timestamp with time zone,
  client_operation_id text,
  request_fingerprint text,
  CONSTRAINT access_recovery_requests_method_check CHECK ((method = ANY (ARRAY['oauth_invite'::text, 'manual_review'::text]))),
  CONSTRAINT access_recovery_requests_owner_user_id_fkey FOREIGN KEY (owner_user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT access_recovery_requests_pkey PRIMARY KEY (id),
  CONSTRAINT access_recovery_requests_requested_by_user_id_fkey FOREIGN KEY (requested_by_user_id) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT access_recovery_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'issued'::text, 'completed'::text, 'cancelled'::text]))),
  CONSTRAINT access_recovery_requests_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.complaints (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  tenant_id bigint NOT NULL,
  site_id bigint NOT NULL,
  subscriber_id bigint,
  title text NOT NULL,
  description text NOT NULL,
  priority text DEFAULT 'normal'::text NOT NULL,
  status text DEFAULT 'open'::text NOT NULL,
  assigned_user_id bigint,
  response text,
  opened_at timestamp with time zone DEFAULT now() NOT NULL,
  resolved_at timestamp with time zone,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT complaints_assigned_user_id_fkey FOREIGN KEY (assigned_user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT complaints_pkey PRIMARY KEY (id),
  CONSTRAINT complaints_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
  CONSTRAINT complaints_site_id_fkey FOREIGN KEY (site_id) REFERENCES sites(id) ON DELETE RESTRICT,
  CONSTRAINT complaints_status_check CHECK ((status = ANY (ARRAY['open'::text, 'assigned'::text, 'in_progress'::text, 'resolved'::text, 'closed'::text]))),
  CONSTRAINT complaints_subscriber_id_fkey FOREIGN KEY (subscriber_id) REFERENCES subscribers(id) ON DELETE SET NULL,
  CONSTRAINT complaints_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.feature_global_control_audit (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  feature_key text NOT NULL,
  actor_user_id bigint,
  before_is_active boolean,
  after_is_active boolean NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT feature_global_control_audit_actor_user_id_fkey FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT feature_global_control_audit_feature_key_fkey FOREIGN KEY (feature_key) REFERENCES feature_catalog(feature_key) ON DELETE CASCADE,
  CONSTRAINT feature_global_control_audit_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS public.generator_owner_provisioning_operations (
  client_operation_id uuid NOT NULL,
  actor_user_id bigint NOT NULL,
  owner_email text NOT NULL,
  request_fingerprint text NOT NULL,
  auth_user_id uuid,
  status text DEFAULT 'pending'::text NOT NULL,
  tenant_id bigint,
  owner_user_id bigint,
  site_id bigint,
  subscription_id bigint,
  response jsonb,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT generator_owner_provisioning_operations_actor_user_id_fkey FOREIGN KEY (actor_user_id) REFERENCES users(id),
  CONSTRAINT generator_owner_provisioning_operations_owner_user_id_fkey FOREIGN KEY (owner_user_id) REFERENCES users(id),
  CONSTRAINT generator_owner_provisioning_operations_pkey PRIMARY KEY (client_operation_id),
  CONSTRAINT generator_owner_provisioning_operations_site_id_fkey FOREIGN KEY (site_id) REFERENCES sites(id),
  CONSTRAINT generator_owner_provisioning_operations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text]))),
  CONSTRAINT generator_owner_provisioning_operations_subscription_id_fkey FOREIGN KEY (subscription_id) REFERENCES tenant_subscriptions(id),
  CONSTRAINT generator_owner_provisioning_operations_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants(id)
);

CREATE TABLE IF NOT EXISTS public.meters (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  tenant_id bigint NOT NULL,
  subscriber_id bigint NOT NULL,
  generator_id bigint,
  serial_number text NOT NULL,
  meter_type text DEFAULT 'manual'::text NOT NULL,
  multiplier numeric(8,3) DEFAULT 1 NOT NULL,
  installed_at timestamp with time zone DEFAULT now() NOT NULL,
  status text DEFAULT 'active'::text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT meters_generator_id_fkey FOREIGN KEY (generator_id) REFERENCES generators(id) ON DELETE SET NULL,
  CONSTRAINT meters_meter_type_check CHECK ((meter_type = ANY (ARRAY['manual'::text, 'digital'::text, 'smart'::text]))),
  CONSTRAINT meters_pkey PRIMARY KEY (id),
  CONSTRAINT meters_serial_number_key UNIQUE (serial_number),
  CONSTRAINT meters_status_check CHECK ((status = ANY (ARRAY['active'::text, 'replaced'::text, 'damaged'::text, 'offline'::text]))),
  CONSTRAINT meters_subscriber_id_fkey FOREIGN KEY (subscriber_id) REFERENCES subscribers(id) ON DELETE CASCADE,
  CONSTRAINT meters_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.password_reset_intents (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  tenant_id bigint NOT NULL,
  site_id bigint,
  target_user_id bigint NOT NULL,
  target_auth_user_id uuid NOT NULL,
  actor_user_id bigint NOT NULL,
  actor_type text NOT NULL,
  status text DEFAULT 'in_progress'::text NOT NULL,
  failure_reason text,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  completed_at timestamp with time zone,
  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
  CONSTRAINT password_reset_intents_actor_type_check CHECK ((actor_type = ANY (ARRAY['tenant_owner'::text, 'platform_admin'::text]))),
  CONSTRAINT password_reset_intents_actor_user_id_fkey FOREIGN KEY (actor_user_id) REFERENCES users(id),
  CONSTRAINT password_reset_intents_pkey PRIMARY KEY (id),
  CONSTRAINT password_reset_intents_site_id_fkey FOREIGN KEY (site_id) REFERENCES sites(id) ON DELETE SET NULL,
  CONSTRAINT password_reset_intents_status_check CHECK ((status = ANY (ARRAY['in_progress'::text, 'completed'::text, 'failed'::text]))),
  CONSTRAINT password_reset_intents_target_user_id_fkey FOREIGN KEY (target_user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT password_reset_intents_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.platform_tariff_policies (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  minimum_price_per_kwh numeric(14,4) NOT NULL,
  maximum_price_per_kwh numeric(14,4) NOT NULL,
  effective_from timestamp with time zone NOT NULL,
  notification_requested boolean DEFAULT false NOT NULL,
  notes text,
  created_by_user_id bigint NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT platform_tariff_policies_check CHECK ((maximum_price_per_kwh >= minimum_price_per_kwh)),
  CONSTRAINT platform_tariff_policies_created_by_user_id_fkey FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT platform_tariff_policies_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS public.subscription_renewal_operations (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  request_key uuid NOT NULL,
  subscription_id bigint NOT NULL,
  request_fingerprint jsonb NOT NULL,
  ends_at timestamp with time zone NOT NULL,
  renewed_addons integer DEFAULT 0 NOT NULL,
  expired_addons integer DEFAULT 0 NOT NULL,
  created_by_user_id bigint NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  package_code text,
  CONSTRAINT subscription_renewal_operations_created_by_user_id_fkey FOREIGN KEY (created_by_user_id) REFERENCES users(id),
  CONSTRAINT subscription_renewal_operations_pkey PRIMARY KEY (id),
  CONSTRAINT subscription_renewal_operations_request_key_key UNIQUE (request_key),
  CONSTRAINT subscription_renewal_operations_subscription_id_fkey FOREIGN KEY (subscription_id) REFERENCES tenant_subscriptions(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.tenant_addon_renewal_decisions (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  tenant_id bigint NOT NULL,
  subscription_id bigint NOT NULL,
  addon_request_id bigint NOT NULL,
  decision text NOT NULL,
  new_duration_days integer,
  created_by_user_id bigint NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT tenant_addon_renewal_decision_subscription_id_addon_request_key UNIQUE (subscription_id, addon_request_id),
  CONSTRAINT tenant_addon_renewal_decisions_addon_request_id_fkey FOREIGN KEY (addon_request_id) REFERENCES tenant_addon_requests(id) ON DELETE CASCADE,
  CONSTRAINT tenant_addon_renewal_decisions_created_by_user_id_fkey FOREIGN KEY (created_by_user_id) REFERENCES users(id),
  CONSTRAINT tenant_addon_renewal_decisions_decision_check CHECK ((decision = ANY (ARRAY['renew'::text, 'expire'::text]))),
  CONSTRAINT tenant_addon_renewal_decisions_new_duration_days_check CHECK (((new_duration_days IS NULL) OR ((new_duration_days >= 1) AND (new_duration_days <= 3650)))),
  CONSTRAINT tenant_addon_renewal_decisions_pkey PRIMARY KEY (id),
  CONSTRAINT tenant_addon_renewal_decisions_subscription_id_fkey FOREIGN KEY (subscription_id) REFERENCES tenant_subscriptions(id) ON DELETE CASCADE,
  CONSTRAINT tenant_addon_renewal_decisions_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.tenant_owner_alerts (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  tenant_id bigint NOT NULL,
  site_id bigint NOT NULL,
  title text NOT NULL,
  message text NOT NULL,
  severity text DEFAULT 'warning'::text NOT NULL,
  created_by_user_id bigint,
  read_at timestamp with time zone,
  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT tenant_owner_alerts_created_by_user_id_fkey FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT tenant_owner_alerts_pkey PRIMARY KEY (id),
  CONSTRAINT tenant_owner_alerts_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'warning'::text, 'critical'::text]))),
  CONSTRAINT tenant_owner_alerts_site_id_fkey FOREIGN KEY (site_id) REFERENCES sites(id) ON DELETE CASCADE,
  CONSTRAINT tenant_owner_alerts_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.user_quick_action_preferences (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  user_id bigint NOT NULL,
  site_id bigint NOT NULL,
  action_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT user_quick_action_preferences_pkey PRIMARY KEY (id),
  CONSTRAINT user_quick_action_preferences_site_id_fkey FOREIGN KEY (site_id) REFERENCES sites(id) ON DELETE CASCADE,
  CONSTRAINT user_quick_action_preferences_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT user_quick_action_preferences_user_id_site_id_key UNIQUE (user_id, site_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS access_recovery_requests_client_operation_id_uidx ON public.access_recovery_requests USING btree (client_operation_id) WHERE (client_operation_id IS NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS access_recovery_requests_pkey ON public.access_recovery_requests USING btree (id);
CREATE INDEX IF NOT EXISTS access_recovery_tenant_status_idx ON public.access_recovery_requests USING btree (tenant_id, status);
CREATE INDEX IF NOT EXISTS complaints_opened_at_idx ON public.complaints USING btree (opened_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS complaints_pkey ON public.complaints USING btree (id);
CREATE INDEX IF NOT EXISTS complaints_tenant_site_status_idx ON public.complaints USING btree (tenant_id, site_id, status);
CREATE UNIQUE INDEX IF NOT EXISTS feature_global_control_audit_pkey ON public.feature_global_control_audit USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS generator_owner_provisioning_auth_uidx ON public.generator_owner_provisioning_operations USING btree (auth_user_id) WHERE (auth_user_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS generator_owner_provisioning_email_idx ON public.generator_owner_provisioning_operations USING btree (lower(owner_email));
CREATE UNIQUE INDEX IF NOT EXISTS generator_owner_provisioning_operations_pkey ON public.generator_owner_provisioning_operations USING btree (client_operation_id);
CREATE UNIQUE INDEX IF NOT EXISTS meters_pkey ON public.meters USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS meters_serial_number_key ON public.meters USING btree (serial_number);
CREATE INDEX IF NOT EXISTS meters_tenant_subscriber_idx ON public.meters USING btree (tenant_id, subscriber_id);
CREATE UNIQUE INDEX IF NOT EXISTS password_reset_intents_active_target_uq ON public.password_reset_intents USING btree (tenant_id, target_user_id) WHERE (status = 'in_progress'::text);
CREATE UNIQUE INDEX IF NOT EXISTS password_reset_intents_pkey ON public.password_reset_intents USING btree (id);
CREATE INDEX IF NOT EXISTS password_reset_intents_target_idx ON public.password_reset_intents USING btree (tenant_id, target_user_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS platform_tariff_policies_pkey ON public.platform_tariff_policies USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS subscription_renewal_operations_pkey ON public.subscription_renewal_operations USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS subscription_renewal_operations_request_key_key ON public.subscription_renewal_operations USING btree (request_key);
CREATE INDEX IF NOT EXISTS subscription_renewal_operations_subscription_idx ON public.subscription_renewal_operations USING btree (subscription_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS tenant_addon_renewal_decision_subscription_id_addon_request_key ON public.tenant_addon_renewal_decisions USING btree (subscription_id, addon_request_id);
CREATE UNIQUE INDEX IF NOT EXISTS tenant_addon_renewal_decisions_pkey ON public.tenant_addon_renewal_decisions USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS tenant_owner_alerts_pkey ON public.tenant_owner_alerts USING btree (id);
CREATE INDEX IF NOT EXISTS tenant_owner_alerts_tenant_site_created_idx ON public.tenant_owner_alerts USING btree (tenant_id, site_id, created_at DESC);
CREATE INDEX IF NOT EXISTS tenant_owner_alerts_unread_idx ON public.tenant_owner_alerts USING btree (tenant_id, site_id, read_at) WHERE (read_at IS NULL);
CREATE UNIQUE INDEX IF NOT EXISTS user_quick_action_preferences_pkey ON public.user_quick_action_preferences USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS user_quick_action_preferences_user_id_site_id_key ON public.user_quick_action_preferences USING btree (user_id, site_id);
CREATE INDEX IF NOT EXISTS user_quick_actions_site_idx ON public.user_quick_action_preferences USING btree (site_id);

