-- Recreate the named permissive policy so a drifted definition cannot survive by name alone.
DROP POLICY IF EXISTS "platform_tariff_policies_platform_admin_only" ON public.platform_tariff_policies;
CREATE POLICY "platform_tariff_policies_platform_admin_only" ON public.platform_tariff_policies
  AS PERMISSIVE FOR ALL TO authenticated
  USING (private.powerhub_is_platform_admin())
  WITH CHECK (private.powerhub_is_platform_admin());

-- A restrictive guard is ANDed with every permissive policy, so an accidental
-- extra permissive policy cannot widen cross-tenant or cross-user access.
DROP POLICY IF EXISTS "platform_tariff_policies_admin_guard" ON public.platform_tariff_policies;
CREATE POLICY "platform_tariff_policies_admin_guard" ON public.platform_tariff_policies
  AS RESTRICTIVE FOR ALL TO authenticated
  USING (private.powerhub_is_platform_admin())
  WITH CHECK (private.powerhub_is_platform_admin());

-- Recreate the named permissive policy so a drifted definition cannot survive by name alone.
DROP POLICY IF EXISTS "quick_actions_owner_only" ON public.user_quick_action_preferences;
CREATE POLICY "quick_actions_owner_only" ON public.user_quick_action_preferences
  AS PERMISSIVE FOR ALL TO authenticated
  USING (((user_id = private.powerhub_current_user_id()) OR private.powerhub_is_platform_admin()))
  WITH CHECK (((user_id = private.powerhub_current_user_id()) OR private.powerhub_is_platform_admin()));

-- A restrictive guard is ANDed with every permissive policy, so an accidental
-- extra permissive policy cannot widen cross-tenant or cross-user access.
DROP POLICY IF EXISTS "quick_actions_owner_guard" ON public.user_quick_action_preferences;
CREATE POLICY "quick_actions_owner_guard" ON public.user_quick_action_preferences
  AS RESTRICTIVE FOR ALL TO authenticated
  USING (((user_id = private.powerhub_current_user_id()) OR private.powerhub_is_platform_admin()))
  WITH CHECK (((user_id = private.powerhub_current_user_id()) OR private.powerhub_is_platform_admin()));

DO $reconcile_trigger$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.complaints'::regclass AND tgname='complaints_set_updated_at' AND NOT tgisinternal) THEN
    EXECUTE 'CREATE TRIGGER complaints_set_updated_at BEFORE UPDATE ON public.complaints FOR EACH ROW EXECUTE FUNCTION powerhub_set_updated_at()';
  END IF;
END $reconcile_trigger$;
DO $reconcile_trigger$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.meters'::regclass AND tgname='meters_set_updated_at' AND NOT tgisinternal) THEN
    EXECUTE 'CREATE TRIGGER meters_set_updated_at BEFORE UPDATE ON public.meters FOR EACH ROW EXECUTE FUNCTION powerhub_set_updated_at()';
  END IF;
END $reconcile_trigger$;
DO $reconcile_trigger$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.user_quick_action_preferences'::regclass AND tgname='quick_actions_set_updated_at' AND NOT tgisinternal) THEN
    EXECUTE 'CREATE TRIGGER quick_actions_set_updated_at BEFORE UPDATE ON public.user_quick_action_preferences FOR EACH ROW EXECUTE FUNCTION powerhub_set_updated_at()';
  END IF;
END $reconcile_trigger$;

DROP FUNCTION IF EXISTS public.powerhub_admin_request_owner_access_recovery(bigint,bigint,text);
DROP FUNCTION IF EXISTS public.powerhub_admin_renew_subscription_with_addons(bigint,bigint,timestamptz,jsonb);
DROP FUNCTION IF EXISTS public.powerhub_admin_renew_subscription_with_addons(bigint,bigint,timestamptz,jsonb,uuid);

CREATE OR REPLACE FUNCTION public.powerhub_admin_complete_generator_owner_provisioning(p_actor_user_id bigint, p_client_operation_id uuid, p_auth_user_id uuid, p_tenant_name text, p_slug text, p_company_name text, p_owner_name text, p_identity_ciphertext text, p_identity_iv text, p_identity_last4 text, p_owner_phone text, p_owner_whatsapp text, p_owner_email text, p_site_name text, p_site_code text, p_package_code text DEFAULT 'basic'::text, p_billing_cycle text DEFAULT 'monthly'::text, p_subscription_status text DEFAULT 'trial'::text, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_trial_duration_days integer DEFAULT 8)
 RETURNS TABLE(success boolean, tenant_id bigint, owner_user_id bigint, site_id bigint, subscription_id bigint, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_role text;
 v_op public.generator_owner_provisioning_operations%rowtype;
 v_started_at timestamptz:=now();
 v_ends_at timestamptz;
 v_tenant_id bigint;
 v_user_id bigint;
 v_site_id bigint;
 v_subscription_id bigint;
 v_package_code text;
begin
 select platform_role into v_role
 from public.users
 where id=p_actor_user_id and role='admin' and account_status='active'
   and platform_role in('platform_owner','platform_admin');

 if v_role is null then
   raise exception 'FORBIDDEN_PLATFORM_ROLE' using errcode='42501';
 end if;

 if p_auth_user_id is null then
   raise exception 'AUTH_USER_REQUIRED' using errcode='22023';
 end if;

 if p_client_operation_id is null then
   raise exception 'CLIENT_OPERATION_REQUIRED' using errcode='P0001';
 end if;

 v_package_code:=lower(nullif(btrim(p_package_code),''));
 perform public.powerhub_validate_package_code(v_package_code);

 if p_billing_cycle not in('monthly','yearly') then
   raise exception 'INVALID_BILLING_CYCLE' using errcode='22023';
 end if;

 if p_subscription_status not in('trial','active','overdue','suspended','cancelled') then
   raise exception 'INVALID_SUBSCRIPTION_STATUS' using errcode='22023';
 end if;

 if p_trial_duration_days is null or p_trial_duration_days<1 or p_trial_duration_days>3650 then
   raise exception 'INVALID_TRIAL_DURATION' using errcode='22023';
 end if;

 perform pg_advisory_xact_lock(hashtext('generator-owner-provision:'||p_client_operation_id::text)::bigint);

 select * into v_op
 from public.generator_owner_provisioning_operations
 where client_operation_id=p_client_operation_id
 for update;

 if not found then
   raise exception 'PROVISIONING_OPERATION_NOT_FOUND' using errcode='P0002';
 end if;

 if v_op.actor_user_id<>p_actor_user_id then
   raise exception 'PROVISIONING_OPERATION_ACTOR_CONFLICT' using errcode='P0001';
 end if;

 if v_op.auth_user_id is not null and v_op.auth_user_id<>p_auth_user_id then
   raise exception 'PROVISIONING_AUTH_USER_CONFLICT' using errcode='P0001';
 end if;

 if v_op.status='completed' then
   return query select true,v_op.tenant_id,v_op.owner_user_id,v_op.site_id,v_op.subscription_id,true;
   return;
 end if;

 if v_op.owner_email<>lower(trim(p_owner_email)) then
   raise exception 'PROVISIONING_EMAIL_CONFLICT' using errcode='P0001';
 end if;

 update public.generator_owner_provisioning_operations
 set auth_user_id=p_auth_user_id,updated_at=now()
 where client_operation_id=p_client_operation_id;

 if exists(select 1 from public.users where auth_user_id=p_auth_user_id and role<>'user') then
   raise exception 'AUTH_USER_ALREADY_MAPPED' using errcode='23505';
 end if;
 if exists(select 1 from public.tenant_owner_profiles where phone=p_owner_phone) then
   raise exception 'OWNER_PHONE_ALREADY_PROVISIONED' using errcode='23505';
 end if;
 if exists(select 1 from public.tenant_owner_profiles where email=lower(p_owner_email)) then
   raise exception 'OWNER_EMAIL_ALREADY_PROVISIONED' using errcode='23505';
 end if;
 if exists(select 1 from public.tenants where slug=p_slug) then
   raise exception 'TENANT_SLUG_ALREADY_EXISTS' using errcode='23505';
 end if;

 v_ends_at:=case
   when p_subscription_status='trial' then v_started_at+make_interval(days=>p_trial_duration_days)
   when p_ends_at is not null then p_ends_at
   when p_billing_cycle='yearly' then v_started_at+interval '1 year'
   else v_started_at+interval '1 month'
 end;

 insert into public.users(
   auth_user_id,name,email,login_method,role,account_status,
   must_change_password,temporary_password_issued_at,last_signed_in
 )
 values(
   p_auth_user_id,p_owner_name,lower(p_owner_email),'supabase','user','active',
   true,v_started_at,v_started_at
 )
 on conflict(auth_user_id) do update set
   name=coalesce(excluded.name,public.users.name),
   email=excluded.email,
   login_method='supabase',
   role='user',
   account_status='active',
   must_change_password=true,
   temporary_password_issued_at=v_started_at,
   last_signed_in=v_started_at
 returning id into v_user_id;

 insert into public.tenants(name,slug,status)
 values(p_tenant_name,p_slug,case when p_subscription_status='cancelled' then 'suspended' else 'active' end)
 returning id into v_tenant_id;

 insert into public.tenant_owner_profiles(
   tenant_id,owner_user_id,full_name,phone,whatsapp_number,email,
   company_name,identity_number_ciphertext,identity_number_iv,
   identity_number_last4,invited_at,claimed_at
 )
 values(
   v_tenant_id,v_user_id,p_owner_name,p_owner_phone,nullif(p_owner_whatsapp,''),
   lower(p_owner_email),nullif(p_company_name,''),p_identity_ciphertext,
   p_identity_iv,p_identity_last4,v_started_at,v_started_at
 );

 insert into public.sites(tenant_id,name,code,status)
 values(v_tenant_id,p_site_name,p_site_code,'active')
 returning id into v_site_id;

 insert into public.tenant_members(
   tenant_id,user_id,role,is_active,membership_status
 )
 values(v_tenant_id,v_user_id,'owner',true,'active');

 insert into public.staff_profiles(
   tenant_id,site_id,user_id,role,is_active
 )
 values(v_tenant_id,v_site_id,v_user_id,'owner',true);

 insert into public.tenant_subscriptions(
   tenant_id,package_code,status,billing_cycle,started_at,ends_at,
   auto_renew,renewal_count,notes,trial_duration_days
 )
 values(
   v_tenant_id,v_package_code,p_subscription_status,p_billing_cycle,
   v_started_at,v_ends_at,false,0,null,
   case when p_subscription_status='trial' then p_trial_duration_days else null end
 )
 returning id into v_subscription_id;

 insert into public.audit_logs(
   tenant_id,site_id,user_id,actor_platform_role,entity_type,entity_id,
   action,after_data,metadata
 )
 values(
   v_tenant_id,v_site_id,p_actor_user_id,v_role,'tenant_subscription',
   v_subscription_id::text,'platform_admin_create_generator_owner_subscription',
   jsonb_build_object(
     'tenantId',v_tenant_id,
     'ownerUserId',v_user_id,
     'packageCode',v_package_code,
     'status',p_subscription_status,
     'trialDurationDays',case when p_subscription_status='trial' then p_trial_duration_days else null end
   ),
   jsonb_build_object(
     'ownerEmail',lower(p_owner_email),
     'ownerPhoneLast4',right(p_owner_phone,4),
     'clientOperationId',p_client_operation_id
   )
 );

 update public.generator_owner_provisioning_operations
 set status='completed',
     tenant_id=v_tenant_id,
     owner_user_id=v_user_id,
     site_id=v_site_id,
     subscription_id=v_subscription_id,
     response=jsonb_build_object(
       'tenantId',v_tenant_id,
       'ownerUserId',v_user_id,
       'siteId',v_site_id,
       'subscriptionId',v_subscription_id,
       'packageCode',v_package_code
     ),
     updated_at=now()
 where client_operation_id=p_client_operation_id;

 return query select true,v_tenant_id,v_user_id,v_site_id,v_subscription_id,false;
end;
$function$;
ALTER FUNCTION public.powerhub_admin_complete_generator_owner_provisioning(bigint, uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, timestamp with time zone, integer) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_admin_complete_generator_owner_provisioning(bigint, uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, timestamp with time zone, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_admin_complete_generator_owner_provisioning(bigint, uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, timestamp with time zone, integer) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_admin_create_tariff_policy(p_actor_user_id bigint, p_minimum_price_per_kwh numeric, p_maximum_price_per_kwh numeric, p_effective_from timestamp with time zone, p_notification_requested boolean DEFAULT false, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(success boolean, policy_id bigint, queued_notifications integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare v_actor public.users%rowtype;v_policy_id bigint;v_queued integer:=0;v_owner_site record;v_channel text; begin if p_minimum_price_per_kwh<0 or p_maximum_price_per_kwh<=0 or p_maximum_price_per_kwh<p_minimum_price_per_kwh then raise exception 'INVALID_TARIFF_RANGE'; end if; if p_effective_from is null then raise exception 'INVALID_EFFECTIVE_FROM'; end if; if p_notes is not null and char_length(p_notes)>2000 then raise exception 'INVALID_NOTES'; end if; select * into v_actor from public.users where id=p_actor_user_id and role='admin' and platform_role in ('platform_owner','platform_admin') and account_status='active' for update; if not found then raise exception 'FORBIDDEN'; end if; insert into public.platform_tariff_policies(minimum_price_per_kwh,maximum_price_per_kwh,effective_from,notification_requested,notes,created_by_user_id,created_at) values(p_minimum_price_per_kwh,p_maximum_price_per_kwh,p_effective_from,p_notification_requested,p_notes,v_actor.id,now()) returning id into v_policy_id; if p_notification_requested then for v_owner_site in select top_profile.tenant_id,top_profile.phone,first_site.id as site_id from public.tenant_owner_profiles top_profile join lateral(select s.id from public.sites s where s.tenant_id=top_profile.tenant_id and s.status<>'archived' order by s.id asc limit 1) first_site on true where top_profile.phone is not null and length(trim(top_profile.phone))>0 order by top_profile.tenant_id loop for v_channel in select tmc.channel from public.tenant_messaging_configurations tmc where tmc.tenant_id=v_owner_site.tenant_id and tmc.is_active=true and tmc.channel in ('whatsapp','sms') order by case when tmc.channel='whatsapp' then 0 else 1 end loop insert into public.notification_messages(tenant_id,channel,event_type,recipient,status,payload,created_at,updated_at) values(v_owner_site.tenant_id,v_channel,'service_alert',trim(v_owner_site.phone),'pending',jsonb_build_object('type','platform_tariff_policy','policyId',v_policy_id,'minimumPricePerKwh',p_minimum_price_per_kwh,'maximumPricePerKwh',p_maximum_price_per_kwh,'effectiveFrom',p_effective_from,'siteId',v_owner_site.site_id),now(),now()); v_queued:=v_queued+1; end loop; if not exists(select 1 from public.tenant_messaging_configurations tmc where tmc.tenant_id=v_owner_site.tenant_id and tmc.is_active=true and tmc.channel in ('whatsapp','sms')) then insert into public.notification_messages(tenant_id,channel,event_type,recipient,status,payload,created_at,updated_at) values(v_owner_site.tenant_id,'whatsapp','service_alert',trim(v_owner_site.phone),'pending',jsonb_build_object('type','platform_tariff_policy','policyId',v_policy_id,'minimumPricePerKwh',p_minimum_price_per_kwh,'maximumPricePerKwh',p_maximum_price_per_kwh,'effectiveFrom',p_effective_from,'siteId',v_owner_site.site_id,'notificationFallback',true),now(),now()); v_queued:=v_queued+1; end if; end loop; end if; insert into public.platform_security_events(event_type,severity,status,title,details,metadata,created_by_user_id) values('security_change','info','success','تحديث التسعيرة الرسمية','تم إنشاء سياسة تسعير جديدة عبر مسار إدارة المنصة.',jsonb_build_object('policyId',v_policy_id,'minimumPricePerKwh',p_minimum_price_per_kwh,'maximumPricePerKwh',p_maximum_price_per_kwh,'effectiveFrom',p_effective_from,'notificationRequested',p_notification_requested,'queuedNotifications',v_queued),v_actor.id); return query select true,v_policy_id,v_queued; end; $function$;
ALTER FUNCTION public.powerhub_admin_create_tariff_policy(bigint, numeric, numeric, timestamp with time zone, boolean, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_admin_create_tariff_policy(bigint, numeric, numeric, timestamp with time zone, boolean, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_admin_create_tariff_policy(bigint, numeric, numeric, timestamp with time zone, boolean, text) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_admin_grant_tenant_addon(p_actor_user_id bigint, p_tenant_id bigint, p_feature_key text, p_quantity integer, p_billing_mode text DEFAULT 'free'::text, p_note text DEFAULT NULL::text, p_request_key uuid DEFAULT NULL::uuid)
 RETURNS TABLE(success boolean, request_id bigint, tenant_id bigint, feature_key text, addon_code text, quantity integer, display_quantity integer, billing_mode text, starts_at timestamp with time zone, ends_at timestamp with time zone, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_actor_role text;
 v_feature_type text;
 v_feature_active boolean;
 v_package_code text;
 v_policy text;
 v_subscription public.tenant_subscriptions%rowtype;
 v_addon_code text;
 v_storage_quantity integer;
 v_display_quantity integer;
 v_site_id bigint;
 v_existing public.tenant_addon_requests%rowtype;
 v_request_id bigint;
 v_now timestamptz:=now();
 v_days integer;
begin
 select platform_role into v_actor_role from public.users
 where id=p_actor_user_id and role='admin' and account_status='active'
   and platform_role in('platform_owner','platform_admin');
 if v_actor_role is null then raise exception 'FORBIDDEN_PLATFORM_ROLE' using errcode='42501'; end if;

 if p_tenant_id is null or not exists(select 1 from public.tenants where id=p_tenant_id) then
   raise exception 'TENANT_NOT_FOUND' using errcode='P0001';
 end if;
 if p_quantity is null or p_quantity<1 then raise exception 'INVALID_ADDON_QUANTITY' using errcode='P0001'; end if;
 if p_billing_mode not in('free','paid') then raise exception 'INVALID_BILLING_MODE' using errcode='P0001'; end if;

 select fc.feature_type,fc.is_active into v_feature_type,v_feature_active
 from public.feature_catalog fc where fc.feature_key=trim(p_feature_key) limit 1;
 if v_feature_type is null then raise exception 'FEATURE_NOT_FOUND' using errcode='P0001'; end if;
 if not v_feature_active then raise exception 'FEATURE_GLOBALLY_DISABLED' using errcode='P0001'; end if;
 if v_feature_type<>'quota' then raise exception 'FEATURE_NOT_ADDON_MANAGEABLE' using errcode='P0001'; end if;

 select ts.* into v_subscription
 from public.tenant_subscriptions ts
 where ts.tenant_id=p_tenant_id and ts.status in('trial','active')
   and (ts.ends_at is null or ts.ends_at>v_now)
 order by ts.created_at desc,ts.id desc limit 1 for update;
 if not found or v_subscription.ends_at is null then raise exception 'SUBSCRIPTION_REQUIRED' using errcode='P0001'; end if;

 v_package_code:=v_subscription.package_code;
 select p.policy into v_policy
 from public.package_feature_policies p
 where p.package_code=v_package_code and p.feature_key=trim(p_feature_key)
 limit 1;
 if coalesce(v_policy,'none') not in('included','addon') then
   raise exception 'FEATURE_NOT_AVAILABLE_IN_PACKAGE' using errcode='P0001';
 end if;

 v_addon_code:=case trim(p_feature_key)
   when 'subscriber_management' then 'subscribers50'
   when 'platform_users' then 'platformUser'
   when 'field_users' then 'fieldUser'
   when 'branch_management' then 'branch'
   when 'sms' then 'sms'
   else null end;
 if v_addon_code is null then raise exception 'FEATURE_NOT_ADDON_MANAGEABLE' using errcode='P0001'; end if;

 if p_feature_key='subscriber_management' then
   if mod(p_quantity,50)<>0 then raise exception 'SUBSCRIBER_ADDON_QUANTITY_MULTIPLE_REQUIRED' using errcode='P0001'; end if;
   v_storage_quantity:=p_quantity/50;
   v_display_quantity:=p_quantity;
 else
   v_storage_quantity:=p_quantity;
   v_display_quantity:=p_quantity;
 end if;

 select s.id into v_site_id from public.sites s
 where s.tenant_id=p_tenant_id and s.status<>'archived'
 order by s.id limit 1;
 if v_site_id is null then raise exception 'TENANT_SITE_REQUIRED_FOR_AUDIT' using errcode='P0001'; end if;

 if p_request_key is not null then
   select * into v_existing from public.tenant_addon_requests
   where request_key=p_request_key for update;
   if found then
     if v_existing.tenant_id<>p_tenant_id or v_existing.addon_code<>v_addon_code
        or v_existing.quantity<>v_storage_quantity or v_existing.billing_mode<>p_billing_mode then
       raise exception 'ADDON_REQUEST_KEY_REUSED' using errcode='P0001';
     end if;
     return query select true,v_existing.id,v_existing.tenant_id,trim(p_feature_key),
       v_existing.addon_code,v_existing.quantity,v_display_quantity,v_existing.billing_mode,
       v_existing.starts_at,v_existing.ends_at,true;
     return;
   end if;
 end if;

 v_days:=greatest(1,ceil(extract(epoch from (v_subscription.ends_at-v_now))/86400.0)::integer);

 insert into public.tenant_addon_requests(
   tenant_id,site_id,requested_by_user_id,addon_code,quantity,status,note,
   created_at,reviewed_at,reviewed_by_user_id,review_note,duration_days,starts_at,ends_at,
   billing_mode,source,request_key
 )
 values(
   p_tenant_id,v_site_id,p_actor_user_id,v_addon_code,v_storage_quantity,'approved',
   nullif(btrim(p_note),''),v_now,v_now,p_actor_user_id,'منح مباشر من إدارة الميزات والحدود.',
   v_days,v_now,v_subscription.ends_at,p_billing_mode,'admin_grant',p_request_key
 )
 returning id into v_request_id;

 insert into public.audit_logs(
   tenant_id,site_id,user_id,actor_platform_role,entity_type,entity_id,action,after_data
 )
 values(
   p_tenant_id,v_site_id,p_actor_user_id,v_actor_role,'tenant_addon_request',
   v_request_id::text,'grant_addon',
   jsonb_build_object(
     'featureKey',trim(p_feature_key),'addonCode',v_addon_code,
     'quantity',v_storage_quantity,'displayQuantity',v_display_quantity,
     'billingMode',p_billing_mode,'startsAt',v_now,'endsAt',v_subscription.ends_at,'note',p_note
   )
 );

 return query select true,v_request_id,p_tenant_id,trim(p_feature_key),v_addon_code,
   v_storage_quantity,v_display_quantity,p_billing_mode,v_now,v_subscription.ends_at,false;
end;
$function$;
ALTER FUNCTION public.powerhub_admin_grant_tenant_addon(bigint, bigint, text, integer, text, text, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_admin_grant_tenant_addon(bigint, bigint, text, integer, text, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_admin_grant_tenant_addon(bigint, bigint, text, integer, text, text, uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_admin_renew_subscription_idempotent(p_actor_user_id bigint, p_tenant_id bigint, p_periods integer, p_client_operation_id text)
 RETURNS TABLE(success boolean, ends_at timestamp with time zone, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_role text;v_sub public.tenant_subscriptions%rowtype;v_site_id bigint;v_base timestamptz;v_period interval;v_ends_at timestamptz;v_op public.offline_sync_operations%rowtype;
begin
 if nullif(trim(p_client_operation_id),'') is null then raise exception 'CLIENT_OPERATION_REQUIRED' using errcode='P0001'; end if;
 select platform_role into v_role from public.users where id=p_actor_user_id and role='admin' and account_status='active' and platform_role in('platform_owner','platform_admin');
 if v_role is null then raise exception 'FORBIDDEN_PLATFORM_ROLE' using errcode='42501'; end if;
 if p_periods<1 or p_periods>24 then raise exception 'INVALID_PERIODS' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtext('subscription-renew:'||p_actor_user_id::text||':'||trim(p_client_operation_id))::bigint);
 select * into v_op from public.offline_sync_operations where user_id=p_actor_user_id and client_operation_id=trim(p_client_operation_id) for update;
 if found then
   if v_op.operation_type<>'subscription_renew' or v_op.tenant_id<>p_tenant_id or v_op.response->>'periods'<>(p_periods::text) then raise exception 'SUBSCRIPTION_RENEW_OPERATION_CONFLICT' using errcode='P0001'; end if;
   return query select true,(v_op.response->>'endsAt')::timestamptz,true; return;
 end if;
 select * into v_sub from public.tenant_subscriptions where tenant_id=p_tenant_id for update;
 if not found then raise exception 'SUBSCRIPTION_NOT_FOUND' using errcode='P0002'; end if;
 select s.id into v_site_id from public.sites s where s.tenant_id=p_tenant_id order by s.id limit 1;
 if v_site_id is null then raise exception 'SITE_NOT_FOUND' using errcode='P0002'; end if;
 v_base:=greatest(v_sub.ends_at,now());
 v_period:=case v_sub.billing_cycle when 'monthly' then make_interval(months=>p_periods) when 'yearly' then make_interval(years=>p_periods) else null end;
 if v_period is null then raise exception 'INVALID_BILLING_CYCLE' using errcode='22023'; end if;
 v_ends_at:=v_base+v_period;
 update public.tenant_subscriptions set status='active',ends_at=v_ends_at,renewal_count=renewal_count+p_periods,last_renewed_at=now(),updated_at=now() where id=v_sub.id;
 update public.tenants set status='active',updated_at=now() where id=p_tenant_id;
 insert into public.audit_logs(tenant_id,site_id,user_id,actor_platform_role,entity_type,entity_id,action,after_data) values(p_tenant_id,v_site_id,p_actor_user_id,v_role,'tenant_subscription',v_sub.id::text,'platform_admin_renew_subscription',jsonb_build_object('periods',p_periods,'billingCycle',v_sub.billing_cycle,'previousEndsAt',v_sub.ends_at,'endsAt',v_ends_at));
 insert into public.offline_sync_operations(tenant_id,site_id,user_id,client_operation_id,operation_type,entity_type,entity_id,response) values(p_tenant_id,v_site_id,p_actor_user_id,trim(p_client_operation_id),'subscription_renew','tenant_subscription',v_sub.id,jsonb_build_object('periods',p_periods,'endsAt',v_ends_at));
 return query select true,v_ends_at,false;
end;
$function$;
ALTER FUNCTION public.powerhub_admin_renew_subscription_idempotent(bigint, bigint, integer, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_admin_renew_subscription_idempotent(bigint, bigint, integer, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_admin_renew_subscription_idempotent(bigint, bigint, integer, text) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_admin_renew_subscription_with_addons(p_actor_user_id bigint, p_subscription_id bigint, p_new_ends_at timestamp with time zone, p_package_code text, p_addon_decisions jsonb, p_request_key uuid)
 RETURNS TABLE(success boolean, ends_at timestamp with time zone, package_code text, renewed_addons integer, expired_addons integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  s public.tenant_subscriptions%rowtype;
  a public.tenant_addon_requests%rowtype;
  d jsonb;
  v_existing public.subscription_renewal_operations%rowtype;
  v_fingerprint jsonb;
  v_tenant_status text;
  v_site_id bigint;
  v_actor_platform_role text;
  v_addon_id bigint;
  v_decision text;
  v_duration int;
  v_new_end timestamptz;
  v_renewed int := 0;
  v_expired int := 0;
begin
  if p_request_key is null then
    raise exception 'RENEWAL_REQUEST_KEY_REQUIRED' using errcode='P0001';
  end if;

  v_fingerprint := jsonb_build_object(
    'subscriptionId', p_subscription_id,
    'endsAt', p_new_ends_at,
    'packageCode', p_package_code,
    'addonDecisions', coalesce(p_addon_decisions,'[]'::jsonb)
  );

  select platform_role into v_actor_platform_role
  from public.users
  where id=p_actor_user_id
    and role='admin'
    and account_status='active'
    and platform_role in ('platform_owner','platform_admin');

  if v_actor_platform_role is null then
    raise exception 'FORBIDDEN_PLATFORM_ROLE' using errcode='42501';
  end if;

  if p_package_code is null or public.powerhub_catalog_package(p_package_code) is null then
    raise exception 'INVALID_RENEWAL_PACKAGE' using errcode='22023';
  end if;

  if not exists (
    select 1
    from jsonb_array_elements(
      coalesce((select value->'packages'
                from public.platform_settings
                where setting_key='subscription_package_catalog'
                  and is_enabled=true
                limit 1),'[]'::jsonb)
    ) package_row
    where lower(trim(package_row->>'code'))=lower(trim(p_package_code))
      and coalesce((package_row->>'active')::boolean,true)=true
  ) then
    raise exception 'RENEWAL_PACKAGE_NOT_ACTIVE' using errcode='P0001';
  end if;

  if jsonb_typeof(coalesce(p_addon_decisions,'[]'::jsonb)) <> 'array' then
    raise exception 'INVALID_ADDON_DECISIONS_PAYLOAD' using errcode='P0001';
  end if;

  select * into s from public.tenant_subscriptions
  where id=p_subscription_id for update;

  if not found then
    raise exception 'SUBSCRIPTION_NOT_FOUND' using errcode='P0001';
  end if;

  select * into v_existing
  from public.subscription_renewal_operations
  where request_key=p_request_key for update;

  if found then
    if v_existing.subscription_id<>p_subscription_id
       or v_existing.request_fingerprint<>v_fingerprint then
      raise exception 'RENEWAL_REQUEST_KEY_REUSED' using errcode='P0001';
    end if;
    return query select true,v_existing.ends_at,
      coalesce(v_existing.package_code,v_existing.request_fingerprint->>'packageCode'),
      v_existing.renewed_addons,v_existing.expired_addons;
    return;
  end if;

  select status into v_tenant_status from public.tenants where id=s.tenant_id;
  if v_tenant_status='archived' or s.status='archived' then
    raise exception 'ARCHIVED_SUBSCRIPTION_RENEWAL_FORBIDDEN' using errcode='42501';
  end if;

  if p_new_ends_at<=now() then
    raise exception 'INVALID_RENEWAL_END_DATE' using errcode='P0001';
  end if;

  select site_id into v_site_id
  from public.tenant_addon_requests
  where tenant_id=s.tenant_id and site_id is not null
  order by created_at desc limit 1;

  if v_site_id is null then
    select id into v_site_id from public.sites
    where tenant_id=s.tenant_id and status<>'archived'
    order by id limit 1;
  end if;

  if v_site_id is null then
    raise exception 'TENANT_SITE_REQUIRED_FOR_AUDIT' using errcode='P0001';
  end if;

  if exists (
    select 1
    from (
      select (x->>'addonRequestId')::bigint addon_request_id,count(*) decision_count
      from jsonb_array_elements(coalesce(p_addon_decisions,'[]'::jsonb)) x
      where jsonb_typeof(x)='object' and (x->>'addonRequestId') ~ '^[0-9]+$'
      group by (x->>'addonRequestId')::bigint having count(*)>1
    ) duplicates
  ) then
    raise exception 'DUPLICATE_ADDON_DECISION' using errcode='P0001';
  end if;

  for d in select * from jsonb_array_elements(coalesce(p_addon_decisions,'[]'::jsonb)) loop
    if jsonb_typeof(d)<>'object' or coalesce(d->>'addonRequestId','') !~ '^[0-9]+$' then
      raise exception 'INVALID_ADDON_REQUEST_ID' using errcode='P0001';
    end if;
    v_addon_id := (d->>'addonRequestId')::bigint;
    v_decision := d->>'decision';
    if v_decision is null or v_decision not in ('renew','expire') then
      raise exception 'INVALID_ADDON_DECISION' using errcode='P0001';
    end if;
    select * into a from public.tenant_addon_requests
    where id=v_addon_id and tenant_id=s.tenant_id for update;
    if not found then raise exception 'ADDON_NOT_FOUND_OR_TENANT_MISMATCH' using errcode='P0001'; end if;
    if a.status<>'approved' then raise exception 'ADDON_NOT_APPROVED' using errcode='P0001'; end if;
    if v_decision='renew' and a.ends_at is not null and a.ends_at<=now() then
      raise exception 'EXPIRED_ADDON_RENEWAL_FORBIDDEN' using errcode='P0001';
    end if;
    if v_decision='renew' then
      if d ? 'durationDays' and d->>'durationDays'<>'' then
        if (d->>'durationDays') !~ '^[0-9]+$' then raise exception 'INVALID_ADDON_DURATION' using errcode='P0001'; end if;
        v_duration := (d->>'durationDays')::int;
      else
        v_duration := coalesce(a.duration_days,30);
      end if;
      if v_duration<1 or v_duration>3650 then raise exception 'INVALID_ADDON_DURATION' using errcode='P0001'; end if;
    end if;
  end loop;

  update public.tenant_subscriptions
  set ends_at=p_new_ends_at,
      package_code=p_package_code,
      status='active',
      renewal_count=renewal_count+1,
      last_renewed_at=now(),
      updated_at=now()
  where id=s.id;

  for d in select * from jsonb_array_elements(coalesce(p_addon_decisions,'[]'::jsonb)) loop
    v_addon_id := (d->>'addonRequestId')::bigint;
    v_decision := d->>'decision';
    select * into a from public.tenant_addon_requests
    where id=v_addon_id and tenant_id=s.tenant_id for update;
    if v_decision='renew' then
      v_duration := case
        when d ? 'durationDays' and d->>'durationDays'<>'' then (d->>'durationDays')::int
        else coalesce(a.duration_days,30)
      end;
      v_new_end := p_new_ends_at + make_interval(days=>v_duration);
      update public.tenant_addon_requests set ends_at=v_new_end,duration_days=v_duration where id=a.id;
      insert into public.tenant_addon_renewal_decisions(
        tenant_id,subscription_id,addon_request_id,decision,new_duration_days,created_by_user_id
      ) values(s.tenant_id,s.id,a.id,'renew',v_duration,p_actor_user_id)
      on conflict(subscription_id,addon_request_id) do update set
        decision='renew',new_duration_days=excluded.new_duration_days,
        created_by_user_id=excluded.created_by_user_id,created_at=now();
      v_renewed := v_renewed+1;
    else
      update public.tenant_addon_requests
      set ends_at=least(coalesce(tenant_addon_requests.ends_at,now()),now())
      where tenant_addon_requests.id=a.id;
      insert into public.tenant_addon_renewal_decisions(
        tenant_id,subscription_id,addon_request_id,decision,created_by_user_id
      ) values(s.tenant_id,s.id,a.id,'expire',p_actor_user_id)
      on conflict(subscription_id,addon_request_id) do update set
        decision='expire',new_duration_days=null,
        created_by_user_id=excluded.created_by_user_id,created_at=now();
      v_expired := v_expired+1;
    end if;
  end loop;

  insert into public.subscription_renewal_operations(
    request_key,subscription_id,request_fingerprint,ends_at,package_code,
    renewed_addons,expired_addons,created_by_user_id
  ) values(
    p_request_key,s.id,v_fingerprint,p_new_ends_at,p_package_code,
    v_renewed,v_expired,p_actor_user_id
  );

  insert into public.audit_logs(
    tenant_id,site_id,user_id,actor_platform_role,
    entity_type,entity_id,action,after_data
  ) values(
    s.tenant_id,v_site_id,p_actor_user_id,v_actor_platform_role,
    'tenant_subscription',s.id::text,'renew_subscription_with_addons',
    jsonb_build_object(
      'newEndsAt',p_new_ends_at,
      'packageCode',p_package_code,
      'renewedAddons',v_renewed,
      'expiredAddons',v_expired,
      'requestKey',p_request_key
    )
  );

  return query select true,p_new_ends_at,p_package_code,v_renewed,v_expired;
end;
$function$;
ALTER FUNCTION public.powerhub_admin_renew_subscription_with_addons(bigint, bigint, timestamp with time zone, text, jsonb, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_admin_renew_subscription_with_addons(bigint, bigint, timestamp with time zone, text, jsonb, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_admin_renew_subscription_with_addons(bigint, bigint, timestamp with time zone, text, jsonb, uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_admin_request_owner_access_recovery(p_actor_user_id bigint, p_tenant_id bigint, p_note text DEFAULT NULL::text, p_client_operation_id text DEFAULT NULL::text, p_request_fingerprint text DEFAULT NULL::text)
 RETURNS TABLE(success boolean, recovery_request_id bigint, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_actor_platform_role text; v_owner_user_id bigint; v_request_id bigint; v_note text; v_existing public.access_recovery_requests%rowtype;
begin
 if nullif(trim(p_client_operation_id),'') is null then raise exception 'INVALID_OPERATION_ID'; end if;
 if nullif(trim(p_request_fingerprint),'') is null then raise exception 'INVALID_REQUEST_FINGERPRINT'; end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-recovery:'||trim(p_client_operation_id),0));
 perform pg_advisory_xact_lock(hashtextextended('owner-recovery-tenant:'||p_tenant_id::text,0));
 select platform_role into v_actor_platform_role from public.users where id=p_actor_user_id and role='admin' and account_status='active' and platform_role in ('platform_owner','platform_admin');
 if v_actor_platform_role is null then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_tenant_id is null or p_tenant_id<=0 then raise exception 'INVALID_TENANT_ID' using errcode='22023'; end if;
 v_note:=nullif(btrim(p_note),''); if v_note is not null and char_length(v_note)>2000 then raise exception 'INVALID_NOTE' using errcode='22023'; end if;
 select * into v_existing from public.access_recovery_requests where client_operation_id=trim(p_client_operation_id) for update;
 if found then
   if v_existing.request_fingerprint is distinct from p_request_fingerprint or v_existing.tenant_id is distinct from p_tenant_id or v_existing.requested_by_user_id is distinct from p_actor_user_id or v_existing.note is distinct from v_note then raise exception 'OPERATION_CONFLICT'; end if;
   return query select true,v_existing.id,true; return;
 end if;
 if not exists(select 1 from public.tenants where id=p_tenant_id) then raise exception 'TENANT_NOT_FOUND' using errcode='P0002'; end if;
 select owner_user_id into v_owner_user_id from public.tenant_owner_profiles where tenant_id=p_tenant_id limit 1;
 if v_owner_user_id is null then raise exception 'OWNER_PROFILE_NOT_FOUND' using errcode='P0002'; end if;
 insert into public.access_recovery_requests(tenant_id,owner_user_id,requested_by_user_id,method,status,note,client_operation_id,request_fingerprint)
 values(p_tenant_id,v_owner_user_id,p_actor_user_id,'oauth_invite','pending',v_note,trim(p_client_operation_id),p_request_fingerprint) returning id into v_request_id;
 insert into public.platform_security_events(event_type,severity,status,title,details,metadata,related_user_id,created_by_user_id)
 values('security_change','info','success','طلب استرداد وصول صاحب مولد','تم إنشاء طلب استرداد وصول موثق دون إرسال قناة خارجية.',jsonb_build_object('tenantId',p_tenant_id,'ownerUserId',v_owner_user_id,'recoveryRequestId',v_request_id,'method','oauth_invite','status','pending','clientOperationId',trim(p_client_operation_id)),v_owner_user_id,p_actor_user_id);
 return query select true,v_request_id,false;
end;
$function$;
ALTER FUNCTION public.powerhub_admin_request_owner_access_recovery(bigint, bigint, text, text, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_admin_request_owner_access_recovery(bigint, bigint, text, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_admin_request_owner_access_recovery(bigint, bigint, text, text, text) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_admin_review_tenant_addon_request(p_actor_user_id bigint, p_request_id bigint, p_decision text, p_note text DEFAULT NULL::text, p_duration_days integer DEFAULT NULL::integer)
 RETURNS TABLE(success boolean, status text, ends_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 r public.tenant_addon_requests%rowtype;
 v_days int;
 v_start timestamptz;
 v_end timestamptz;
 v_actor_platform_role text;
 v_subscription_end timestamptz;
begin
 select platform_role into v_actor_platform_role
 from public.users
 where id=p_actor_user_id
   and role='admin'
   and account_status='active'
   and platform_role in ('platform_owner','platform_admin');

 if v_actor_platform_role is null then
   raise exception 'FORBIDDEN_PLATFORM_ROLE' using errcode='42501';
 end if;

 if p_decision not in ('approved','rejected') then
   raise exception 'INVALID_DECISION' using errcode='P0001';
 end if;

 select * into r
 from public.tenant_addon_requests
 where id=p_request_id
 for update;

 if not found then
   raise exception 'ADDON_REQUEST_NOT_FOUND' using errcode='P0001';
 end if;

 if r.status not in ('pending','reviewing') then
   raise exception 'ADDON_REQUEST_NOT_PENDING' using errcode='P0001';
 end if;

 if p_decision='rejected' then
   update public.tenant_addon_requests
   set status='rejected',reviewed_at=now(),reviewed_by_user_id=p_actor_user_id,review_note=p_note
   where id=r.id;

   return query select true,'rejected',null::timestamptz;
   return;
 end if;

 v_start:=now();

 if r.addon_code='sms' then
   select ts.ends_at into v_subscription_end
   from public.tenant_subscriptions ts
   where ts.tenant_id=r.tenant_id
   order by ts.created_at desc,ts.id desc
   limit 1;

   if v_subscription_end is null or v_subscription_end<=now() then
     raise exception 'SMS_SUBSCRIPTION_EXPIRED' using errcode='P0001';
   end if;

   v_end:=v_subscription_end;
   v_days:=greatest(1,ceil(extract(epoch from (v_end-v_start))/86400.0)::integer);
 else
   v_days:=coalesce(p_duration_days,r.duration_days,30);

   if v_days<1 or v_days>3650 then
     raise exception 'INVALID_ADDON_DURATION' using errcode='P0001';
   end if;

   v_end:=v_start+make_interval(days=>v_days);
 end if;

 update public.tenant_addon_requests
 set status='approved',
     duration_days=v_days,
     starts_at=v_start,
     ends_at=v_end,
     reviewed_at=now(),
     reviewed_by_user_id=p_actor_user_id,
     review_note=p_note
 where id=r.id;

 insert into public.audit_logs(
   tenant_id,site_id,user_id,actor_platform_role,entity_type,entity_id,action,after_data
 )
 values(
   r.tenant_id,r.site_id,p_actor_user_id,v_actor_platform_role,
   'tenant_addon_request',r.id::text,'approve_addon',
   jsonb_build_object(
     'addonCode',r.addon_code,
     'quantity',r.quantity,
     'durationDays',v_days,
     'startsAt',v_start,
     'endsAt',v_end
   )
 );

 return query select true,'approved',v_end;
end;
$function$;
ALTER FUNCTION public.powerhub_admin_review_tenant_addon_request(bigint, bigint, text, text, integer) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_admin_review_tenant_addon_request(bigint, bigint, text, text, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_admin_review_tenant_addon_request(bigint, bigint, text, text, integer) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_admin_set_feature_global(p_actor_user_id bigint, p_feature_key text, p_is_active boolean)
 RETURNS TABLE(feature_key text, is_active boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_role text; v_setting_key text; v_before boolean;
begin
  select platform_role into v_role from public.users
  where id=p_actor_user_id and role='admin' and platform_role in ('platform_owner','platform_admin') and account_status='active';
  if not found then raise exception 'PLATFORM_ADMIN_FORBIDDEN' using errcode='P0001'; end if;
  select is_active into v_before from public.feature_catalog where feature_key=p_feature_key;
  if not found then raise exception 'FEATURE_NOT_FOUND' using errcode='P0001'; end if;

  insert into public.feature_global_control_audit(feature_key,actor_user_id,before_is_active,after_is_active)
  values(p_feature_key,p_actor_user_id,v_before,p_is_active);

  update public.feature_catalog set is_active=p_is_active,updated_at=now() where feature_key=p_feature_key;
  v_setting_key:=case p_feature_key when 'subscriber_portal_logo' then 'subscriber_portal_logo' when 'payment_documentation' then 'payment_documentation' when 'branch_management' then 'branch_feature' else null end;
  if v_setting_key is not null then
    insert into public.platform_settings(setting_key,is_enabled,value,message,updated_at)
    values(v_setting_key,p_is_active,jsonb_build_object('feature',p_feature_key),'إدارة إتاحة الميزة من مركز الميزات والحدود.',now())
    on conflict(setting_key) do update set is_enabled=excluded.is_enabled,message=excluded.message,updated_at=now();
  end if;
  return query select p_feature_key,p_is_active;
end; $function$;
ALTER FUNCTION public.powerhub_admin_set_feature_global(bigint, text, boolean) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_admin_set_feature_global(bigint, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_admin_set_feature_global(bigint, text, boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_admin_set_tenant_feature_control(p_actor_user_id bigint, p_tenant_id bigint, p_feature_key text, p_status text, p_limit_mode text, p_manual_limit integer, p_reason text DEFAULT NULL::text)
 RETURNS TABLE(tenant_id bigint, feature_key text, status text, limit_mode text, manual_limit integer, override_reason text, updated_by_user_id bigint, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_before jsonb; v_now timestamptz:=now(); v_policy text; v_package_code text; v_feature_active boolean:=false; v_allowed boolean:=false; v_updated boolean:=false;
begin
  if not exists(select 1 from public.users u where u.id=p_actor_user_id and u.role='admin' and u.platform_role in ('platform_owner','platform_admin') and u.account_status='active') then raise exception 'PLATFORM_ADMIN_FORBIDDEN' using errcode='P0001'; end if;
  if p_status not in ('inherit','enabled','disabled') then raise exception 'INVALID_FEATURE_STATUS' using errcode='P0001'; end if;
  if p_limit_mode not in ('inherit','manual','unlimited') then raise exception 'INVALID_FEATURE_LIMIT_MODE' using errcode='P0001'; end if;
  if p_limit_mode='manual' and (p_manual_limit is null or p_manual_limit<0) then raise exception 'INVALID_FEATURE_MANUAL_LIMIT' using errcode='P0001'; end if;
  if p_limit_mode<>'manual' and p_manual_limit is not null then raise exception 'MANUAL_LIMIT_REQUIRES_MANUAL_MODE' using errcode='P0001'; end if;
  if not exists(select 1 from public.tenants t where t.id=p_tenant_id) then raise exception 'TENANT_NOT_FOUND' using errcode='P0001'; end if;
  select fc.is_active into v_feature_active from public.feature_catalog fc where fc.feature_key=p_feature_key limit 1;
  if not found then raise exception 'FEATURE_NOT_FOUND' using errcode='P0001'; end if;
  if not v_feature_active then raise exception 'FEATURE_GLOBALLY_DISABLED' using errcode='P0001'; end if;
  perform pg_advisory_xact_lock(hashtext('tenant-feature-control:'||p_tenant_id::text||':'||p_feature_key)::bigint);
  select to_jsonb(c)-'id' into v_before from public.tenant_feature_controls c where c.tenant_id=p_tenant_id and c.feature_key=p_feature_key for update;
  select ts.package_code into v_package_code from public.tenant_subscriptions ts where ts.tenant_id=p_tenant_id and ts.status in ('trial','active') and (ts.ends_at is null or ts.ends_at>now()) order by ts.created_at desc limit 1;
  select p.policy into v_policy from public.package_feature_policies p where p.package_code=v_package_code and p.feature_key=p_feature_key;
  v_allowed:=coalesce(v_policy in ('included','addon'),false);
  if p_status='enabled' and not v_allowed then raise exception 'FEATURE_NOT_AVAILABLE_IN_PACKAGE' using errcode='P0001'; end if;
  update public.tenant_feature_controls c set status=p_status,limit_mode=p_limit_mode,manual_limit=p_manual_limit,override_reason=nullif(btrim(p_reason),''),updated_by_user_id=p_actor_user_id,updated_at=v_now where c.tenant_id=p_tenant_id and c.feature_key=p_feature_key;
  v_updated:=found;
  if not v_updated then insert into public.tenant_feature_controls(tenant_id,feature_key,status,limit_mode,manual_limit,override_reason,updated_by_user_id,updated_at) values(p_tenant_id,p_feature_key,p_status,p_limit_mode,p_manual_limit,nullif(btrim(p_reason),''),p_actor_user_id,v_now); end if;
  if p_feature_key in ('subscriber_portal_logo','payment_documentation') then
    update public.tenant_feature_entitlements e set is_enabled=(p_status='enabled'),activated_by_user_id=case when p_status='enabled' then p_actor_user_id else null end,activated_at=case when p_status='enabled' then v_now else null end,updated_at=v_now where e.tenant_id=p_tenant_id and e.feature_key=p_feature_key;
    v_updated:=found;
    if p_status='inherit' then delete from public.tenant_feature_entitlements e where e.tenant_id=p_tenant_id and e.feature_key=p_feature_key;
    elsif not v_updated then insert into public.tenant_feature_entitlements(tenant_id,feature_key,is_enabled,activated_by_user_id,activated_at,created_at,updated_at) values(p_tenant_id,p_feature_key,p_status='enabled',case when p_status='enabled' then p_actor_user_id else null end,case when p_status='enabled' then v_now else null end,v_now,v_now); end if;
  end if;
  insert into public.tenant_feature_control_audit(tenant_id,feature_key,actor_user_id,action,before_data,after_data,reason)
  values(p_tenant_id,p_feature_key,p_actor_user_id,case when v_before is null then 'create' else 'update' end,v_before,(select to_jsonb(c)-'id' from public.tenant_feature_controls c where c.tenant_id=p_tenant_id and c.feature_key=p_feature_key),nullif(btrim(p_reason),''));
  return query select c.tenant_id,c.feature_key,c.status,c.limit_mode,c.manual_limit,c.override_reason,c.updated_by_user_id,c.updated_at from public.tenant_feature_controls c where c.tenant_id=p_tenant_id and c.feature_key=p_feature_key;
end;
$function$;
ALTER FUNCTION public.powerhub_admin_set_tenant_feature_control(bigint, bigint, text, text, text, integer, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_admin_set_tenant_feature_control(bigint, bigint, text, text, text, integer, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_admin_set_tenant_feature_control(bigint, bigint, text, text, text, integer, text) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_get_active_addon_delta(p_tenant_id bigint, p_addon_code text, p_at timestamp with time zone DEFAULT now())
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
 select coalesce(sum(quantity * case when addon_code='subscribers50' then 50 else 1 end),0)::integer
 from public.tenant_addon_requests
 where tenant_id=p_tenant_id and addon_code=p_addon_code and status='approved'
   and (starts_at is null or starts_at<=p_at)
   and (ends_at is null or ends_at>p_at)
$function$;
ALTER FUNCTION public.powerhub_get_active_addon_delta(bigint, text, timestamp with time zone) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_get_active_addon_delta(bigint, text, timestamp with time zone) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_get_active_addon_delta(bigint, text, timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION public.powerhub_prepare_addon_renewal_choices(p_subscription_id bigint)
 RETURNS TABLE(addon_request_id bigint, addon_code text, quantity integer, ends_at timestamp with time zone, remaining_days integer, renewal_status text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
 select a.id,a.addon_code,a.quantity,a.ends_at,
        greatest(0,ceil(extract(epoch from (a.ends_at-now()))/86400.0))::integer,
        case when a.ends_at is null or a.ends_at>now() then 'active' else 'expired' end
 from public.tenant_addon_requests a
 join public.tenant_subscriptions s on s.tenant_id=a.tenant_id
 where s.id=p_subscription_id and a.status='approved'
 order by a.ends_at nulls last,a.id
$function$;
ALTER FUNCTION public.powerhub_prepare_addon_renewal_choices(bigint) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.powerhub_prepare_addon_renewal_choices(bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.powerhub_prepare_addon_renewal_choices(bigint) TO service_role;

